    10→import { isToolResultMessage } from "./role-normalizer.ts";
    11→import { formatToolOutputForSidebar, getTruncatedPreview } from "./tool-helpers.ts";
    12→
    13→export type ToolPreview = NonNullable<ToolCard["preview"]>;
    14→
    15→function resolveCanvasPreviewSandbox(preview: ToolPreview): string {
