    18→
    19→function normalizeContent(content: unknown): Array<Record<string, unknown>> {
    20→  if (!Array.isArray(content)) {
    21→    return [];
    22→  }
    23→  return content.filter(Boolean) as Array<Record<string, unknown>>;
    24→}
    25→
    26→function coerceArgs(value: unknown): unknown {
    27→  if (typeof value !== "string") {
    28→    return value;
    29→  }
    30→  const trimmed = value.trim();
    31→  if (!trimmed) {
    32→    return value;
    33→  }
    34→  if (!trimmed.startsWith("{") && !trimmed.startsWith("[")) {
    35→    return value;
    36→  }
    37→  try {
    38→    return JSON.parse(trimmed);
    39→  } catch {
    40→    return value;
    41→  }
    42→}
    43→
    44→function extractToolText(item: Record<string, unknown>): string | undefined {
    45→  if (typeof item.text === "string") {
    46→    return item.text;
    47→  }
    48→  if (typeof item.content === "string") {
    49→    return item.content;
    50→  }
    51→  if (Array.isArray(item.content)) {
    52→    const parts = item.content.flatMap((entry) => {
    53→      if (!entry || typeof entry !== "object") {
    54→        return [];
    55→      }
    56→      const text = (entry as { text?: unknown }).text;
    57→      return typeof text === "string" ? [text] : [];
    58→    });
    59→    if (parts.length > 0) {
    60→      return parts.join("\n");
    61→    }
    62→  }
    63→  return undefined;
    64→}
    65→
    66→export function extractToolPreview(
    67→  outputText: string | undefined,
    68→  toolName: string | undefined,
    69→): ToolCard["preview"] | undefined {
    70→  return extractCanvasFromText(outputText, toolName);
    71→}
    72→
    73→function resolveToolCardId(
    74→  item: Record<string, unknown>,
    75→  message: Record<string, unknown>,
    76→  index: number,
    77→  prefix = "tool",
    78→): string {
    79→  const explicitId =
    80→    (typeof item.id === "string" && item.id.trim()) ||
    81→    (typeof item.toolCallId === "string" && item.toolCallId.trim()) ||
    82→    (typeof item.tool_call_id === "string" && item.tool_call_id.trim()) ||
    83→    (typeof item.callId === "string" && item.callId.trim()) ||
    84→    (typeof message.toolCallId === "string" && message.toolCallId.trim()) ||
    85→    (typeof message.tool_call_id === "string" && message.tool_call_id.trim()) ||
