    97→
    98→function serializeToolInput(args: unknown): string | undefined {
    99→  if (args === undefined || args === null) {
   100→    return undefined;
   101→  }
   102→  if (typeof args === "string") {
   103→    return args;
   104→  }
   105→  try {
   106→    return JSON.stringify(args, null, 2);
   107→  } catch {
   108→    if (typeof args === "number" || typeof args === "boolean" || typeof args === "bigint") {
   109→      return String(args);
   110→    }
   111→    if (typeof args === "symbol") {
   112→      return args.description ? `Symbol(${args.description})` : "Symbol()";
   113→    }
   114→    return Object.prototype.toString.call(args);
   115→  }
   116→}
   117→
   118→function formatPayloadForSidebar(
   119→  text: string | undefined,
   120→  language: "json" | "text" = "text",
   121→): string {
   122→  if (!text?.trim()) {
   123→    return "";
   124→  }
   125→  if (language === "json") {
   126→    return `\`\`\`json
   127→${text}
   128→\`\`\``;
   129→  }
   130→  const formatted = formatToolOutputForSidebar(text);
   131→  if (formatted.includes("```")) {
   132→    return formatted;
   133→  }
   134→  return `\`\`\`text
   135→${text}
   136→\`\`\``;
   137→}
   138→
   139→function findLatestCard(cards: ToolCard[], id: string, name: string): ToolCard | undefined {
   140→  for (let i = cards.length - 1; i >= 0; i--) {
   141→    const card = cards[i];
   142→    if (!card) {
   143→      continue;
   144→    }
   145→    if (card.id === id || (card.name === name && !card.outputText)) {
   146→      return card;
   147→    }
   148→  }
   149→  return undefined;
   150→}
   151→
   152→export function extractToolCards(message: unknown, prefix = "tool"): ToolCard[] {
   153→  const m = message as Record<string, unknown>;
   154→  const content = normalizeContent(m.content);
   155→  const cards: ToolCard[] = [];
   156→
   157→  for (let index = 0; index < content.length; index++) {
   158→    const item = content[index] ?? {};
   159→    const kind = (typeof item.type === "string" ? item.type : "").toLowerCase();
   160→    const isToolCall =
   161→      ["toolcall", "tool_call", "tooluse", "tool_use"].includes(kind) ||
   162→      (typeof item.name === "string" &&
   163→        (item.arguments != null || item.args != null || item.input != null));
   164→    if (isToolCall) {
   165→      const args = coerceArgs(item.arguments ?? item.args ?? item.input);
   166→      cards.push({
   167→        id: resolveToolCardId(item, m, index, prefix),
   168→        name: (item.name as string) ?? "tool",
   169→        args,
   170→        inputText: serializeToolInput(args),
   171→      });
   172→      continue;
   173→    }
   174→
   175→    if (kind === "toolresult" || kind === "tool_result") {
   176→      const name = typeof item.name === "string" ? item.name : "tool";
   177→      const cardId = resolveToolCardId(item, m, index, prefix);
   178→      const existing = findLatestCard(cards, cardId, name);
   179→      const text = extractToolText(item);
   180→      const preview = extractToolPreview(text, name);
   181→      if (existing) {
   182→        existing.outputText = text;
   183→        existing.preview = preview;
   184→        continue;
   185→      }
   186→      cards.push({
   187→        id: cardId,
   188→        name,
   189→        outputText: text,
   190→        preview,
   191→      });
   192→    }
   193→  }
   194→
   195→  const role = typeof m.role === "string" ? m.role.toLowerCase() : "";
   196→  const isStandaloneToolMessage =
   197→    isToolResultMessage(message) ||
   198→    role === "tool" ||
   199→    role === "function" ||
   200→    typeof m.toolName === "string" ||
   201→    typeof m.tool_name === "string";
   202→
   203→  if (isStandaloneToolMessage && cards.length === 0) {
   204→    const name =
   205→      (typeof m.toolName === "string" && m.toolName) ||
   206→      (typeof m.tool_name === "string" && m.tool_name) ||
   207→      "tool";
   208→    const text = extractTextCached(message) ?? undefined;
   209→    cards.push({
   210→      id: resolveToolCardId({}, m, 0, prefix),
   211→      name,
   212→      outputText: text,
