   215→  }
   216→
   217→  return cards;
   218→}
   219→
   220→export function buildToolCardSidebarContent(card: ToolCard): string {
   221→  const display = resolveToolDisplay({ name: card.name, args: card.args });
   222→  const detail = formatToolDetail(display);
   223→  const sections = [`## ${display.label}`, `**Tool:** \`${display.name}\``];
   224→
   225→  if (detail) {
   226→    sections.push(`**Summary:** ${detail}`);
