   229→  if (card.inputText?.trim()) {
   230→    const inputIsJson = typeof card.args === "object" && card.args !== null;
   231→    sections.push(
   232→      `### Tool input\n${formatPayloadForSidebar(card.inputText, inputIsJson ? "json" : "text")}`,
   233→    );
   234→  }
   235→
   236→  if (card.outputText?.trim()) {
   237→    sections.push(`### Tool output\n${formatToolOutputForSidebar(card.outputText)}`);
   238→  } else {
   239→    sections.push(`### Tool output\n*No output — tool completed successfully.*`);
   240→  }
