   309→            preview.kind === "canvas"
   310→              ? resolveEmbedSandbox(options?.embedSandboxMode ?? "scripts")
   311→              : resolveCanvasPreviewSandbox(preview),
   312→        })}
   313→      </div>
   314→    </div>
   315→  `;
