   537→  const preview = card.preview;
   538→  const hasText = Boolean(card.outputText?.trim());
   539→  const hasPreview = Boolean(preview);
   540→  const sidebarContent =
   541→    preview?.kind === "canvas"
   542→      ? buildPreviewSidebarContent(preview, card.outputText)
   543→      : buildSidebarContent(buildToolCardSidebarContent(card));
   544→  const actionContent = sidebarContent ?? buildSidebarContent(buildToolCardSidebarContent(card));
   545→  const canClick = Boolean(onOpenSidebar);
   546→  const handleClick = canClick ? () => onOpenSidebar?.(actionContent) : undefined;
   547→  const isShort = hasText && !hasPreview && (card.outputText?.length ?? 0) <= 240;
   548→  const showCollapsed = hasText && !hasPreview && !isShort;
   549→  const showInline = hasText && !hasPreview && isShort;
   550→  const isEmpty = !hasText && !hasPreview;
