   580→          : nothing}
   581→      </div>
   582→      ${detail ? html`<div class="chat-tool-card__detail">${detail}</div>` : nothing}
   583→      ${isEmpty ? html`<div class="chat-tool-card__status-text muted">Completed</div>` : nothing}
   584→      ${preview
