    70→} | null {
    71→  const normalized = normalizeMessage(toolMessage);
    72→  const cards = extractToolCards(toolMessage, "preview");
    73→  for (let index = cards.length - 1; index >= 0; index--) {
    74→    const card = cards[index];
    75→    if (card?.preview?.kind === "canvas") {
