   799→
   800→function isLocalAssistantAttachmentSource(source: string): boolean {
   801→  const trimmed = source.trim();
   802→  if (/^\/(?:__openclaw__|media|api\/chat\/media\/outgoing)\//.test(trimmed)) {
   803→    return false;
   804→  }
   805→  return (
   806→    trimmed.startsWith("file://") ||
   807→    trimmed.startsWith("~") ||
   808→    trimmed.startsWith("/") ||
   809→    /^[a-zA-Z]:[\\/]/.test(trimmed)
   810→  );
   811→}
   812→
   813→function normalizeLocalAttachmentPath(source: string): string | null {
   814→  const trimmed = source.trim();
   815→  if (!isLocalAssistantAttachmentSource(trimmed)) {
   816→    return null;
   817→  }
   818→  if (trimmed.startsWith("file://")) {
   819→    try {
   820→      const url = new URL(trimmed);
   821→      const pathname = decodeURIComponent(url.pathname);
   822→      if (/^\/[a-zA-Z]:\//.test(pathname)) {
   823→        return pathname.slice(1);
   824→      }
   825→      return pathname;
   826→    } catch {
   827→      return null;
   828→    }
   829→  }
   830→  if (trimmed.startsWith("~")) {
   831→    return null;
   832→  }
   833→  return trimmed;
   834→}
   835→
   836→function resolveHomeCandidatesFromRoots(localMediaPreviewRoots: readonly string[]): string[] {
   837→  const candidates = new Set<string>();
   838→  for (const root of localMediaPreviewRoots) {
   839→    const normalized = canonicalizeLocalPathForComparison(root.trim());
   840→    const unixHome = normalized.match(/^(\/Users\/[^/]+|\/home\/[^/]+)(?:\/|$)/);
   841→    if (unixHome?.[1]) {
   842→      candidates.add(unixHome[1]);
   843→      continue;
   844→    }
   845→    const windowsHome = normalized.match(/^([a-z]:\/Users\/[^/]+)(?:\/|$)/i);
   846→    if (windowsHome?.[1]) {
   847→      candidates.add(windowsHome[1]);
   848→    }
   849→  }
   850→  return [...candidates];
   851→}
   852→
   853→function canonicalizeLocalPathForComparison(value: string): string {
   854→  let slashNormalized = value.replace(/\\/g, "/").replace(/\/+$/, "");
   855→  if (/^\/[a-zA-Z]:\//.test(slashNormalized)) {
   856→    slashNormalized = slashNormalized.slice(1);
   857→  }
   858→  if (/^[a-zA-Z]:\//.test(slashNormalized)) {
   859→    return slashNormalized.toLowerCase();
   860→  }
   861→  return slashNormalized;
   862→}
   863→
   864→function isLocalAttachmentPreviewAllowed(
   865→  source: string,
   866→  localMediaPreviewRoots: readonly string[],
   867→): boolean {
   868→  const normalizedSource = normalizeLocalAttachmentPath(source);
   869→  const comparableSources = normalizedSource
   870→    ? [canonicalizeLocalPathForComparison(normalizedSource)]
   871→    : source.trim().startsWith("~")
   872→      ? resolveHomeCandidatesFromRoots(localMediaPreviewRoots).map((home) =>
   873→          canonicalizeLocalPathForComparison(source.trim().replace(/^~(?=$|[\\/])/, home)),
   874→        )
   875→      : [];
   876→  if (comparableSources.length === 0) {
   877→    return false;
   878→  }
   879→  return localMediaPreviewRoots.some((root) => {
   880→    const normalizedRoot = canonicalizeLocalPathForComparison(root.trim());
   881→    return (
   882→      normalizedRoot.length > 0 &&
   883→      comparableSources.some(
   884→        (comparableSource) =>
   885→          comparableSource === normalizedRoot || comparableSource.startsWith(`${normalizedRoot}/`),
   886→      )
   887→    );
   888→  });
   889→}
   890→
   891→function buildAssistantAttachmentUrl(
   892→  source: string,
   893→  basePath?: string,
   894→  mediaTicket?: string | null,
   895→): string {
   896→  if (!isLocalAssistantAttachmentSource(source)) {
   897→    return source;
   898→  }
   899→  const normalizedBasePath =
   900→    basePath && basePath !== "/" ? (basePath.endsWith("/") ? basePath.slice(0, -1) : basePath) : "";
   901→  const params = new URLSearchParams({ source });
   902→  const normalizedMediaTicket = mediaTicket?.trim();
   903→  if (normalizedMediaTicket) {
   904→    params.set("mediaTicket", normalizedMediaTicket);
   905→  }
   906→  return `${normalizedBasePath}/__openclaw__/assistant-media?${params.toString()}`;
   907→}
   908→
   909→function isManagedOutgoingImageSource(source: string): boolean {
   910→  const trimmed = source.trim();
   911→  if (trimmed.startsWith("/api/chat/media/outgoing/")) {
   912→    return true;
   913→  }
   914→  try {
   915→    const parsed = new URL(trimmed, window.location.origin);
   916→    return (
   917→      parsed.origin === window.location.origin &&
   918→      parsed.pathname.startsWith("/api/chat/media/outgoing/")
   919→    );
   920→  } catch {
   921→    return false;
   922→  }
   923→}
   924→
   925→function resolveManagedOutgoingImageRequesterSessionKey(source: string): string | null {
   926→  try {
   927→    const parsed = new URL(source, window.location.origin);
   928→    const parts = parsed.pathname.split("/");
   929→    const encodedSessionKey = parts[5];
   930→    return encodedSessionKey ? decodeURIComponent(encodedSessionKey) : null;
   931→  } catch {
   932→    return null;
   933→  }
   934→}
   935→
   936→function buildManagedOutgoingImageFetchUrl(source: string, basePath?: string): string {
   937→  if (!source.startsWith("/")) {
   938→    return source;
   939→  }
   940→  const normalizedBasePath =
   941→    basePath && basePath !== "/" ? (basePath.endsWith("/") ? basePath.slice(0, -1) : basePath) : "";
   942→  return `${normalizedBasePath}${source}`;
   943→}
   944→
   945→async function resolveManagedOutgoingImageBlobUrl(
   946→  source: string,
   947→  opts?: ImageRenderOptions,
   948→): Promise<string | null> {
   949→  const authToken = opts?.authToken?.trim() ?? "";
   950→  const fetchUrl = buildManagedOutgoingImageFetchUrl(source, opts?.basePath);
   951→  const cacheKey = `${fetchUrl}::${authToken}`;
   952→  const cached = managedImageBlobUrlResolvedCache.get(cacheKey);
   953→  if (cached) {
   954→    return cached;
   955→  }
   956→  const missAt = managedImageBlobUrlMissCache.get(cacheKey);
   957→  if (missAt && Date.now() - missAt < MANAGED_IMAGE_BLOB_URL_MISS_RETRY_MS) {
   958→    return null;
   959→  }
   960→  let pending = managedImageBlobUrlCache.get(cacheKey);
   961→  if (!pending) {
   962→    pending = (async () => {
   963→      const requesterSessionKey = resolveManagedOutgoingImageRequesterSessionKey(source);
   964→      const headers = new Headers({ Accept: "image/*" });
   965→      if (authToken) {
   966→        headers.set("Authorization", `Bearer ${authToken}`);
   967→      }
   968→      if (requesterSessionKey) {
   969→        headers.set("x-openclaw-requester-session-key", requesterSessionKey);
   970→      }
   971→      const res = await fetch(fetchUrl, {
   972→        method: "GET",
   973→        headers,
   974→        credentials: "same-origin",
   975→      });
   976→      if (!res.ok) {
   977→        managedImageBlobUrlMissCache.set(cacheKey, Date.now());
   978→        return null;
   979→      }
   980→      const blob = await res.blob();
   981→      if (!blob.type.startsWith("image/")) {
   982→        managedImageBlobUrlMissCache.set(cacheKey, Date.now());
   983→        return null;
   984→      }
   985→      const blobUrl = URL.createObjectURL(blob);
   986→      managedImageBlobUrlResolvedCache.set(cacheKey, blobUrl);
   987→      managedImageBlobUrlMissCache.delete(cacheKey);
   988→      return blobUrl;
   989→    })().finally(() => {
   990→      managedImageBlobUrlCache.delete(cacheKey);
   991→    });
   992→    managedImageBlobUrlCache.set(cacheKey, pending);
   993→  }
   994→  return pending;
   995→}
   996→
   997→function buildAssistantAttachmentMetaUrl(source: string, basePath?: string): string {
   998→  const attachmentUrl = buildAssistantAttachmentUrl(source, basePath);
   999→  return `${attachmentUrl}${attachmentUrl.includes("?") ? "&" : "?"}meta=1`;
  1000→}
  1001→
  1002→function clearAssistantAttachmentRefreshTimer(cacheKey: string) {
  1003→  const timer = assistantAttachmentRefreshTimers.get(cacheKey);
  1004→  if (timer) {
  1005→    clearTimeout(timer);
  1006→    assistantAttachmentRefreshTimers.delete(cacheKey);
  1007→  }
  1008→}
  1009→
  1010→function scheduleAssistantAttachmentRefresh(
  1011→  cacheKey: string,
  1012→  availability: AssistantAttachmentAvailability,
  1013→  onRequestUpdate: (() => void) | undefined,
  1014→) {
  1015→  clearAssistantAttachmentRefreshTimer(cacheKey);
  1016→  if (
  1017→    availability.status !== "available" ||
  1018→    !availability.mediaTicket ||
  1019→    !availability.mediaTicketExpiresAt ||
  1020→    !onRequestUpdate
  1021→  ) {
  1022→    return;
  1023→  }
  1024→  const refreshInMs = Math.max(
  1025→    0,
  1026→    availability.mediaTicketExpiresAt -
  1027→      Date.now() -
  1028→      ASSISTANT_ATTACHMENT_MEDIA_TICKET_REFRESH_SKEW_MS,
  1029→  );
  1030→  const timer = setTimeout(() => {
  1031→    assistantAttachmentRefreshTimers.delete(cacheKey);
  1032→    const cached = assistantAttachmentAvailabilityCache.get(cacheKey);
  1033→    if (cached?.status !== "available" || cached.mediaTicket !== availability.mediaTicket) {
  1034→      return;
  1035→    }
  1036→    assistantAttachmentAvailabilityCache.delete(cacheKey);
  1037→    onRequestUpdate();
  1038→  }, refreshInMs);
  1039→  assistantAttachmentRefreshTimers.set(cacheKey, timer);
  1040→}
  1041→
  1042→function resolveAssistantAttachmentAvailability(
  1043→  source: string,
  1044→  localMediaPreviewRoots: readonly string[],
  1045→  basePath: string | undefined,
  1046→  authToken: string | null | undefined,
  1047→  onRequestUpdate: (() => void) | undefined,
  1048→): AssistantAttachmentAvailability {
  1049→  if (!isLocalAssistantAttachmentSource(source)) {
  1050→    return { status: "available" };
  1051→  }
  1052→  if (!isLocalAttachmentPreviewAllowed(source, localMediaPreviewRoots)) {
  1053→    return { status: "unavailable", reason: "Outside allowed folders", checkedAt: Date.now() };
  1054→  }
  1055→  const normalizedAuthToken = authToken?.trim() ?? "";
  1056→  const cacheKey = `${basePath ?? ""}::${normalizedAuthToken}::${source}`;
  1057→  const cached = assistantAttachmentAvailabilityCache.get(cacheKey);
  1058→  if (cached) {
  1059→    const now = Date.now();
  1060→    if (
  1061→      cached.status === "unavailable" &&
  1062→      now - cached.checkedAt >= ASSISTANT_ATTACHMENT_UNAVAILABLE_RETRY_MS
  1063→    ) {
  1064→      assistantAttachmentAvailabilityCache.delete(cacheKey);
  1065→    } else if (
  1066→      cached.status === "available" &&
  1067→      cached.mediaTicket &&
  1068→      (!cached.mediaTicketExpiresAt ||
  1069→        cached.mediaTicketExpiresAt - now <= ASSISTANT_ATTACHMENT_MEDIA_TICKET_REFRESH_SKEW_MS)
  1070→    ) {
  1071→      assistantAttachmentAvailabilityCache.delete(cacheKey);
  1072→    } else {
  1073→      scheduleAssistantAttachmentRefresh(cacheKey, cached, onRequestUpdate);
  1074→      return cached;
  1075→    }
  1076→  }
  1077→  clearAssistantAttachmentRefreshTimer(cacheKey);
  1078→  assistantAttachmentAvailabilityCache.set(cacheKey, { status: "checking" });
  1079→  if (typeof fetch === "function") {
  1080→    const headers = new Headers({ Accept: "application/json" });
  1081→    if (normalizedAuthToken) {
  1082→      headers.set("Authorization", `Bearer ${normalizedAuthToken}`);
  1083→    }
  1084→    void fetch(buildAssistantAttachmentMetaUrl(source, basePath), {
  1085→      method: "GET",
  1086→      headers,
  1087→      credentials: "same-origin",
  1088→    })
  1089→      .then(async (res) => {
  1090→        const payload = (await res.json().catch(() => null)) as {
  1091→          available?: boolean;
  1092→          mediaTicket?: string;
  1093→          mediaTicketExpiresAt?: string;
  1094→          reason?: string;
  1095→        } | null;
  1096→        if (payload?.available === true) {
  1097→          const mediaTicket = payload.mediaTicket?.trim();
  1098→          const mediaTicketExpiresAt = Date.parse(payload.mediaTicketExpiresAt ?? "");
  1099→          if (mediaTicket && !Number.isFinite(mediaTicketExpiresAt)) {
  1100→            clearAssistantAttachmentRefreshTimer(cacheKey);
  1101→            assistantAttachmentAvailabilityCache.set(cacheKey, {
  1102→              status: "unavailable",
  1103→              reason: "Attachment unavailable",
  1104→              checkedAt: Date.now(),
  1105→            });
  1106→            return;
  1107→          }
  1108→          const availability: AssistantAttachmentAvailability = {
  1109→            status: "available",
  1110→            ...(mediaTicket ? { mediaTicket, mediaTicketExpiresAt } : {}),
  1111→          };
  1112→          assistantAttachmentAvailabilityCache.set(cacheKey, availability);
  1113→          scheduleAssistantAttachmentRefresh(cacheKey, availability, onRequestUpdate);
  1114→        } else {
  1115→          clearAssistantAttachmentRefreshTimer(cacheKey);
  1116→          assistantAttachmentAvailabilityCache.set(cacheKey, {
  1117→            status: "unavailable",
  1118→            reason: payload?.reason?.trim() || "Attachment unavailable",
  1119→            checkedAt: Date.now(),
  1120→          });
  1121→        }
  1122→      })
  1123→      .catch(() => {
  1124→        clearAssistantAttachmentRefreshTimer(cacheKey);
  1125→        assistantAttachmentAvailabilityCache.set(cacheKey, {
  1126→          status: "unavailable",
  1127→          reason: "Attachment unavailable",
  1128→          checkedAt: Date.now(),
  1129→        });
  1130→      })
  1131→      .finally(() => {
  1132→        onRequestUpdate?.();
  1133→      });
  1134→  }
  1135→  return { status: "checking" };
  1136→}
