  1311→/**
  1312→ * Max characters for auto-detecting and pretty-printing JSON.
  1313→ * Prevents DoS from large JSON payloads in assistant/tool messages.
  1314→ */
  1315→const MAX_JSON_AUTOPARSE_CHARS = 20_000;
  1316→
  1317→/**
  1318→ * Detect whether a trimmed string is a JSON object or array.
  1319→ * Must start with `{`/`[` and end with `}`/`]` and parse successfully.
  1320→ * Size-capped to prevent render-loop DoS from large JSON messages.
  1321→ */
  1322→function detectJson(text: string): { parsed: unknown; pretty: string } | null {
  1323→  const t = text.trim();
  1324→
  1325→  // Enforce size cap to prevent UI freeze from multi-MB JSON payloads
  1326→  if (t.length > MAX_JSON_AUTOPARSE_CHARS) {
  1327→    return null;
  1328→  }
  1329→
  1330→  if ((t.startsWith("{") && t.endsWith("}")) || (t.startsWith("[") && t.endsWith("]"))) {
  1331→    try {
  1332→      const parsed = JSON.parse(t);
  1333→      return { parsed, pretty: JSON.stringify(parsed, null, 2) };
  1334→    } catch {
  1335→      return null;
  1336→    }
  1337→  }
  1338→  return null;
  1339→}
  1340→
  1341→/** Build a short summary label for collapsed JSON (type + key count or array length). */
  1342→function jsonSummaryLabel(parsed: unknown): string {
  1343→  if (Array.isArray(parsed)) {
  1344→    return `Array (${parsed.length} item${parsed.length === 1 ? "" : "s"})`;
  1345→  }
  1346→  if (parsed && typeof parsed === "object") {
  1347→    const keys = Object.keys(parsed as Record<string, unknown>);
  1348→    if (keys.length <= 4) {
  1349→      return `{ ${keys.join(", ")} }`;
  1350→    }
  1351→    return `Object (${keys.length} keys)`;
  1352→  }
  1353→  return "JSON";
  1354→}
